#!/bin/sh
# GPxPatch GP3RT for Windows: the GPxPatch screen of GP3RT as a Windows program
# (32-bit, runs on 32- and 64-bit Windows; SDL2 linked in, so a single .exe).
# Needs llvm-mingw and the SDL2 mingw development files (see WINBUILD below) and the
# headers generated by build_linux.sh (icons_data.h, ui_i18n.h, ui_fonts.h).
set -e
cd "$(dirname "$0")"
WINBUILD=${WINBUILD:-/home/claude/winsdl}
LM=$(ls -d $WINBUILD/llvm-mingw-*/ | head -n1)
SDL=$(ls -d $WINBUILD/SDL2-*/i686-w64-mingw32 | head -n1)
CC="$LM/bin/i686-w64-mingw32-gcc"; RC="$LM/bin/i686-w64-mingw32-windres"
OUT=build/win-gpx; mkdir -p $OUT/obj
for h in host/icons_data.h host/ui_i18n.h host/ui_fonts.h; do [ -f $h ] || { echo "run build_linux.sh first ($h)"; exit 1; }; done
CFLAGS="-O2 -std=gnu11 -DWIN32_LEAN_AND_MEAN -DNOMINMAX -D_WIN32_WINNT=0x0601 -I$SDL/include/SDL2 -Ihost -Wall -Wno-unused-function -Wno-unused-parameter -Wno-format-truncation"
$CC $CFLAGS -w -c host/nk_sdl.c -o $OUT/obj/nk_sdl.o
for f in host/gpxui.c host/win/lx_win.c host/win/win_main.c host/win/icons_win.c; do $CC $CFLAGS -c $f -o $OUT/obj/$(basename $f .c).o; done
$CC -c host/win/chkstk.S -o $OUT/obj/chkstk.o
(cd host/win && $RC -O coff app.rc -o ../../$OUT/obj/app.res.o)
$CC -mwindows -static -o "$OUT/GPxPatch GP3RT.exe" $OUT/obj/*.o $SDL/lib/libSDL2.a \
    -lsetupapi -lwinmm -limm32 -lversion -lole32 -loleaut32 -lgdi32 -luser32 -lshell32 -luuid -ladvapi32 -lcfgmgr32 -lm
$LM/bin/llvm-strip "$OUT/GPxPatch GP3RT.exe"
echo "built $OUT/GPxPatch GP3RT.exe"
